def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    counts={v:sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    mark=min((v for v in counts if v not in (0,)),key=lambda v:counts[v])
    bg=max(counts,key=counts.get)
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==mark]
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    shape={(r-r0,c-c0) for r,c in pts}; sh=max(r for r,c in shape)+1; sw=max(c for r,c in shape)+1
    for dr in range(h-sh+1):
      for dc in range(w-sw+1):
        if all(grid[dr+r][dc+c]==bg for r,c in shape):
          for r,c in shape: out[dr+r][dc+c]=mark
    return out
